data class ProdukUiState(val memuat: Boolean = true, val produk: List<Produk> = emptyList(), val error: String? = null)

@HiltViewModel
class ProdukViewModel @Inject constructor(private val repo: ProdukRepository) : ViewModel() {
    private val _state = MutableStateFlow(ProdukUiState())
    val state: StateFlow<ProdukUiState> = _state.asStateFlow()

    init { muat() }

    fun muat() = viewModelScope.launch {
        _state.update { it.copy(memuat = true, error = null) }
        repo.daftar()
            .onSuccess { ps -> _state.update { it.copy(memuat = false, produk = ps) } }
            .onFailure { e -> _state.update { it.copy(memuat = false, error = e.message ?: "Gagal memuat") } }
    }
}

