class Produk {
  final String nama;
  final int harga;
  const Produk({required this.nama, required this.harga}) : assert(harga > 0);

  factory Produk.fromJson(Map<String, dynamic> j) => Produk(nama: j['nama'] as String, harga: j['harga'] as int);

  Produk copyWith({String? nama, int? harga}) => Produk(nama: nama ?? this.nama, harga: harga ?? this.harga);

  String get labelHarga => 'Rp$harga';

  @override
  String toString() => 'Produk($nama, $labelHarga)';
}

