}

sealed class Hasil<T> {}
class Sukses<T> extends Hasil<T> { final T data; Sukses(this.data); }
class Gagal<T> extends Hasil<T> { final String pesan; Gagal(this.pesan); }
class Memuat<T> extends Hasil<T> {}

String tampilkan(Hasil<List<String>> h) => switch (h) {
  Memuat() => 'Memuat...',
  Sukses(:final data) => '${data.length} produk',
  Gagal(:final pesan) => 'Error: $pesan',
};

void main() {
