class SaldoKurang implements Exception {
  final int kurang;
  SaldoKurang(this.kurang);
  @override
  String toString() => 'Saldo kurang Rp$kurang';
}

void bayar(int saldo, String input) {
  try {
    final tagihan = int.parse(input);
    if (tagihan > saldo) throw SaldoKurang(tagihan - saldo);
    print('Berhasil bayar $tagihan');
  } on FormatException {
    print('Input bukan angka: $input');
  } on SaldoKurang catch (e) {
    print(e);
  } finally {
    print('-- selesai --');
  }
}

void main() {
  bayar(100000, '75000');
  bayar(100000, 'abc');
  bayar(100000, '150000');
}

