class Item {
  final String nama;
  final int harga, qty;
  const Item(this.nama, this.harga, this.qty);
  int get subtotal => harga * qty;
}

({int subtotal, int ppn, int total}) hitung(List<Item> items, {double tarifPpn = 0.12}) {
  final sub = items.fold(0, (s, i) => s + i.subtotal);
  final ppn = (sub * tarifPpn).round();
  return (subtotal: sub, ppn: ppn, total: sub + ppn);
}

void main() {
  final h = hitung([Item('Kopi Gayo', 85000, 2), Item('Gula Aren', 28000, 1)]);
  print('Subtotal ${h.subtotal}, PPN ${h.ppn}, Total ${h.total}');
}

