# --- Python ---
def transfer(saldo, jumlah):
    if jumlah <= 0:
        return "Jumlah tidak valid"
    if jumlah > saldo:
        return "Saldo tidak cukup"
    if jumlah > 10_000_000:
        return "Melebihi limit harian"
    return "OK, sisa " + f"{saldo - jumlah:,}".replace(",", ".")

