class TombolUtama extends StatelessWidget {
  const TombolUtama({super.key, required this.label, required this.onPressed, this.memuat = false});
  final String label;
  final VoidCallback? onPressed;
  final bool memuat;
  @override
  Widget build(BuildContext context) => FilledButton(
        onPressed: memuat ? null : onPressed,
        child: memuat
            ? Semantics(label: 'Sedang memproses', child: const SizedBox.square(dimension: 20, child: CircularProgressIndicator(strokeWidth: 2)))
            : Text(label),
      );
}

String pesanError(Object e) => switch (e) {
  DioException(response: Response(statusCode: 401)) => 'Email atau kata sandi salah',
  DioException(response: Response(statusCode: 429)) => 'Terlalu banyak percobaan. Coba lagi dalam 1 menit',
  DioException(type: DioExceptionType.connectionError) => 'Tidak ada koneksi internet',
  _ => 'Terjadi kesalahan. Coba lagi',
};

