ALTER TABLE produk ADD COLUMN versi INTEGER DEFAULT 1;
-- dua kasir membaca produk 1 dengan versi 1, kasir A menyimpan duluan:
UPDATE produk SET stok = stok - 1, versi = versi + 1 WHERE id = 1 AND versi = 1;
-- kasir B masih membawa versi 1, update-nya tidak mengenai baris mana pun:
UPDATE produk SET stok = stok - 2, versi = versi + 1 WHERE id = 1 AND versi = 1;
SELECT id, stok, versi FROM produk WHERE id = 1;

