WITH jual AS (
  SELECT pr.kategori, pr.nama, SUM(d.qty) AS unit
  FROM detail d JOIN produk pr ON pr.id = d.produk_id GROUP BY pr.id
)
SELECT * FROM (
  SELECT kategori, nama, unit, ROW_NUMBER() OVER (PARTITION BY kategori ORDER BY unit DESC) AS urut FROM jual
) WHERE urut = 1;

