SELECT b.judul, GROUP_CONCAT(p.nama, ', ') AS penulis
FROM buku b JOIN buku_penulis bp ON bp.buku_id = b.id JOIN penulis p ON p.id = bp.penulis_id
GROUP BY b.id;
